const frames = {
  schedule(callback) {
    const request = requestAnimationFrame;
    return request(callback);
  },
  request: undefined,
  delegate: undefined,
};

export function hasFrames() {
  return typeof requestAnimationFrame;
}

export function tryFrame() {
  try {
    frames.schedule(() => {});
    return "scheduled";
  } catch (e) {
    return `${e.name}: ${e.message}`;
  }
}
